//! App-specific ambient TypeScript declarations.

use super::contract::{self, ParamKind};
use std::fmt::Write;

/// The text of `zant.i18n.d.ts` for the default-locale catalog's keys and contracts,
/// and the list of available locales.
pub fn declarations(locales: &[&str], messages: &[(&str, &contract::Contract)]) -> String {
    let mut out = String::from(
        "// Generated by zant from locales/*.json — do not edit.\ndeclare module \"zant\" {\n",
    );
    let mut locales = locales.to_vec();
    locales.sort_unstable();
    out.push_str("  interface I18nLocales {");
    if !locales.is_empty() {
        out.push('\n');
        for locale in locales {
            out.push_str("    ");
            string_literal(&mut out, locale);
            out.push_str(": true;\n");
        }
        out.push_str("  ");
    }
    out.push_str("}\n  interface I18nMessages {");
    let mut messages = messages.to_vec();
    messages.sort_unstable_by_key(|(key, _)| *key);
    if !messages.is_empty() {
        out.push('\n');
        for (key, contract) in messages {
            out.push_str("    ");
            string_literal(&mut out, key);
            out.push_str(": ");
            if contract.params.is_empty() {
                out.push_str("undefined");
            } else {
                let mut params: Vec<_> = contract.params.iter().collect();
                params.sort_unstable_by_key(|param| &param.name);
                out.push_str("{ ");
                for (index, param) in params.iter().enumerate() {
                    if index > 0 {
                        out.push_str("; ");
                    }
                    out.push_str(&param.name);
                    out.push_str(match param.kind {
                        ParamKind::Number => ": number",
                        ParamKind::String => ": string",
                        ParamKind::Text => ": string | number",
                    });
                }
                out.push_str(" }");
            }
            out.push_str(";\n");
        }
        out.push_str("  ");
    }
    out.push_str("}\n}\n");
    out
}

fn string_literal(out: &mut String, text: &str) {
    out.push('"');
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() || matches!(c, '\u{2028}' | '\u{2029}') => {
                write!(out, "\\u{:04x}", c as u32).unwrap();
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::i18n::{contract, parse_message};

    #[test]
    fn golden_sorts_locales_keys_and_parameters() {
        let add = contract(&parse_message("Add").unwrap()).unwrap();
        let items = contract(&parse_message("{count, number}").unwrap()).unwrap();
        let mut welcome = contract(&parse_message("{name}{when, number}").unwrap()).unwrap();
        welcome.params.reverse();
        assert_eq!(
            declarations(
                &["zh-CN", "en"],
                &[
                    ("home.welcome", &welcome),
                    ("home.items", &items),
                    ("home.add", &add),
                ],
            ),
            r#"// Generated by zant from locales/*.json — do not edit.
declare module "zant" {
  interface I18nLocales {
    "en": true;
    "zh-CN": true;
  }
  interface I18nMessages {
    "home.add": undefined;
    "home.items": { count: number };
    "home.welcome": { name: string | number; when: number };
  }
}
"#
        );
    }

    #[test]
    fn golden_empty_interfaces() {
        assert_eq!(
            declarations(&[], &[]),
            r#"// Generated by zant from locales/*.json — do not edit.
declare module "zant" {
  interface I18nLocales {}
  interface I18nMessages {}
}
"#
        );
    }

    #[test]
    fn escapes_string_literals_and_preserves_unicode() {
        let empty = contract::Contract { params: vec![] };
        let text = "中\"\\\u{2028}\u{2029}\n\r\t\0\u{8}\u{c}\u{1f}\u{7f}\u{85}";
        let escaped = r#""中\"\\\u2028\u2029\n\r\t\u0000\u0008\u000c\u001f\u007f\u0085""#;
        let actual = declarations(&[text], &[(text, &empty)]);
        assert_eq!(
            actual,
            format!(
                "// Generated by zant from locales/*.json — do not edit.\n\
declare module \"zant\" {{\n  interface I18nLocales {{\n    {escaped}: true;\n  }}\n  \
interface I18nMessages {{\n    {escaped}: undefined;\n  }}\n}}\n"
            )
        );
    }
}
